use crate::{model::*,unit_support::*};
fn count(g:&Game)->usize{g.effects.iter().filter(|e|matches!(e,Effect::Declare{declaration:d}if d.ability.key==crate::bq044::KEY)).count()}
#[test]fn bq044_only_actual_personal_character_sacrifice(){for cause in [RemovalCause::Sacrifice,RemovalCause::Destroy,RemovalCause::Lethal]{let mut g=game();field(&mut g,"BQ044",0);let victim=field(&mut g,"JC125",0);g.remove_dead(&victim,cause);assert_eq!(count(&g),usize::from(matches!(cause,RemovalCause::Sacrifice)));}for seat in [1,2,3]{let mut g=game();field(&mut g,"BQ044",0);let victim=field(&mut g,"JC125",seat);g.remove_dead(&victim,RemovalCause::Sacrifice);assert_eq!(count(&g),0);}}
#[test]fn bq044_optional_payment_and_enemy_chooses_current_character(){for discount in 0..=3{let mut g=game();field(&mut g,"BQ044",0);let victim=field(&mut g,"JC125",0);let enemy=field(&mut g,"JC125",2);fund(&mut g,0,"JC049",3);g.players[0].society_zone.loss_control=discount;g.remove_dead(&victim,RemovalCause::Sacrifice);g.drive().unwrap();restore(&mut g);choose(&mut g,vec!["accept".into()]);let f=g.stack.last().unwrap().frame.as_ref().unwrap();assert_eq!(f.money_units(0),(3-discount) as usize);assert!(f.targets.is_empty());crate::jc029_tests::pass_top(&mut g);choose(&mut g,vec!["p2".into()]);assert_eq!(g.pending.as_ref().unwrap().seat,2);choose(&mut g,vec![enemy.clone()]);assert!(g.board(&enemy).is_none());restore(&mut g);}}
#[test]fn bq044_hidden_destroy_and_duplicate_observation_boundaries(){let mut g=game();let source=field(&mut g,"BQ044",0);g.board_mut(&source).unwrap().face_down=true;let v=field(&mut g,"JC125",0);g.remove_dead(&v,RemovalCause::Sacrifice);assert_eq!(count(&g),0);g.board_mut(&source).unwrap().face_down=false;let v=field(&mut g,"JC125",0);g.board_mut(&v).unwrap().face_down=true;g.remove_dead(&v,RemovalCause::Sacrifice);assert_eq!(count(&g),0);let v=field(&mut g,"JC125",0);g.remove_dead(&v,RemovalCause::Sacrifice);let d=g.effects.iter().find(|e|matches!(e,Effect::Declare{declaration:d}if d.ability.key==crate::bq044::KEY)).unwrap().clone();g.effects.push_back(d);assert!(Game::from_persisted(&serde_json::to_string(&g).unwrap()).is_err());}
#[test]fn bq044_catalog_original_identity_and_closed_wip(){let c=crate::catalog::card("BQ044");assert!(!c.supported);assert_eq!(c.loyalty,vec!["红色"]);assert_eq!(c.permanent_icons.influence,1);assert_eq!(c.temporary_icons.influence,0);assert_eq!(c.magic,"鲜血");assert_current_serial_catalog();crate::rules::validate_definitions(crate::rules::definitions()).unwrap();assert!(!crate::core_zone::is_core("BQ044"));}
fn offered()->Game{let mut g=game();field(&mut g,"BQ044",0);let v=field(&mut g,"JC125",0);fund(&mut g,0,"JC049",3);g.remove_dead(&v,RemovalCause::Sacrifice);g.drive().unwrap();g}
#[test]fn bq044_decline_empty_enemy_and_source_sacrifice(){let mut g=offered();choose(&mut g,vec![]);assert!(g.stack.is_empty()&&g.pending.is_none());assert_eq!(g.players[0].assets.iter().filter(|c|c.exhausted).count(),0);let mut g=game();let source=field(&mut g,"BQ044",0);fund(&mut g,0,"JC049",3);g.remove_dead(&source,RemovalCause::Sacrifice);g.drive().unwrap();choose(&mut g,vec!["accept".into()]);crate::jc029_tests::pass_top(&mut g);choose(&mut g,vec!["p2".into()]);assert!(g.pending.is_none()&&g.stack.is_empty());restore(&mut g);}
#[test]fn bq044_attachment_choice_and_game_room_corruption_rejected(){let mut g=offered();let host=field(&mut g,"JC125",2);let c=g.make_card("JC073",2);let id=c.id.clone();g.attachments.push(Attachment{card:c,host_id:host});let hidden=field(&mut g,"JC125",2);g.board_mut(&hidden).unwrap().face_down=true;choose(&mut g,vec!["accept".into()]);crate::jc029_tests::pass_top(&mut g);choose(&mut g,vec!["p2".into()]);assert!(!g.pending.as_ref().unwrap().choice.options.iter().any(|o|o.id==hidden));let room=crate::jc029_tests::envelope(&g);let restored=crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).unwrap();assert_eq!(serde_json::to_value(&restored.game).unwrap(),serde_json::to_value(&g).unwrap());for n in 0..3{let mut bad=room.clone();if n==0{bad.game.pending.as_mut().unwrap().seat=3;}else{let ChoiceResolution::Frame{frame,..}=&mut bad.game.pending.as_mut().unwrap().resolution else{panic!()};if n==1{frame.already_paid.clear();}else{bad.game.effects.push_back(Effect::Frame{frame:frame.clone()});}}assert!(Game::from_persisted(&serde_json::to_string(&bad.game).unwrap()).is_err());assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());}let p=g.pending.clone().unwrap();reject(&mut g,2,Action{choice_id:Some(p.choice.id),selected:Some(vec![id.clone()]),amount:Some(1),..Action::new("choose")});choose(&mut g,vec![id.clone()]);assert!(!g.attachments.iter().any(|a|a.card.id==id));restore(&mut g);}
#[test]fn bq044_real_spell_room_commands_duplicate_and_restore(){use crate::abi112_review_play_tests::Trace;let mut g=game();field(&mut g,"BQ044",0);let dead=field(&mut g,"JC125",0);let enemy=field(&mut g,"JC125",2);fund(&mut g,0,"JC096",2);fund(&mut g,0,"JC049",3);let spell=held(&mut g,"JZ54",0);let mut t=Trace::new_preserving_rng(g,"bq044-prepared-real-spell-sacrifice-trigger".into(),944);t.action(0,Action{card_id:Some(spell),target_id:Some("p0".into()),..Action::new("play")});t.until_pending();t.choose(vec![dead]);t.until_pending();assert!(matches!(&t.room.game.pending.as_ref().unwrap().resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==crate::bq044::KEY));t.choose(vec!["accept".into()]);t.until_pending();t.choose(vec!["p2".into()]);t.choose(vec![enemy.clone()]);assert!(t.room.game.board(&enemy).is_none()&&t.room.game.pending.is_none()&&t.room.game.stack.is_empty());let mut value=t.value();for s in value["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let result=r.transition(s["seat"].as_u64().unwrap() as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(result.outcome,"rejected");assert_eq!(result.state,s["expected"]["state"]);assert!(!result.changed&&result.journal.is_empty());s["duplicate"]=serde_json::to_value(result).unwrap();}if let Ok(path)=std::env::var("BQ044_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec(&value).unwrap()).unwrap();}}
#[test]fn bq044_simultaneous_self_and_other_sacrifice_and_no_funds(){let mut g=game();let source=field(&mut g,"BQ044",0);let other=field(&mut g,"JC125",0);let wave=[source,other].into_iter().map(|id|{let(r,c)=g.board(&id).unwrap();let s=g.source_snapshot(c,Some(r));(id,RemovalCause::Sacrifice,s)}).collect();g.remove_death_batch(wave);assert_eq!(count(&g),2);restore(&mut g);g.drive().unwrap();assert!(g.pending.is_none()&&g.stack.is_empty());restore(&mut g);}
#[test]fn bq044_nested_or_transplanted_program_is_rejected(){use crate::rules::*;let mut a=crate::bq044::definition().abilities.remove(0);a.ops=vec![Op::ForEachLivingPlayer(a.ops.clone())];assert!(crate::bq044::related(&a));assert!(validate_ability("BQ044",&a).is_err());a.key="foreign".into();a.event=None;assert!(validate_ability("JC125",&a).is_err());let mut ds=definitions().clone();ds.insert("JC125".into(),with_abilities(vec![a]));assert!(validate_definitions(&ds).is_err());}
